=SQL("WITH params AS ( SELECT ""周"" AS week_label, ""日期"" AS date_label FROM ""日期表"" WHERE trim(coalesce(cast(""日期"" AS text), '')) <> '' LIMIT 1 ), seed_from_board AS ( SELECT DISTINCT lower(trim(cast(""店铺ID"" AS text))) AS shop_id, CASE WHEN lower(trim(cast(""店铺ID"" AS text))) = '1036978929' THEN '马来-shopee-mall店- veloree _ home decor' WHEN lower(trim(cast(""店铺ID"" AS text))) = '1736897676' AND trim(cast(""出库SKU分类"" AS text)) = '辅助条码' THEN '泰国-shopee-c店-veloree | home decor' WHEN lower(trim(cast(""店铺ID"" AS text))) = '1736897676' THEN '商业分析-泰国-shopee-c店-veloree' ELSE lower(trim(cast(""店铺"" AS text))) END AS shop, trim(cast(""SPU分类"" AS text)) AS category, CASE WHEN trim(cast(""主货号"" AS text)) <> '' THEN trim(cast(""主货号"" AS text)) ELSE trim(cast(""主商品货号"" AS text)) END AS main_key, CASE WHEN trim(cast(""主货号"" AS text)) <> '' THEN trim(cast(""主货号"" AS text)) ELSE trim(cast(""主商品货号"" AS text)) END AS seed_sku FROM ""大盘"" WHERE trim(coalesce(cast(""店铺ID"" AS text), '')) <> '' AND trim(coalesce(cast(""主商品货号"" AS text), '')) NOT IN ('', '#N/A') ), seed_from_erp AS ( SELECT DISTINCT lower(trim(cast(""店铺ID"" AS text))) AS shop_id, CASE WHEN lower(trim(cast(""店铺ID"" AS text))) = '1036978929' THEN '马来-shopee-mall店- veloree _ home decor' WHEN lower(trim(cast(""店铺ID"" AS text))) = '1736897676' THEN '商业分析-泰国-shopee-c店-veloree' ELSE lower(trim(cast(""店铺"" AS text))) END AS shop, trim(cast(""出库SKU分类"" AS text)) AS category, CASE WHEN trim(cast(""出库SKU分类"" AS text)) = '辅助条码' THEN upper(trim(cast(""系统SKU"" AS text))) ELSE trim(cast(""主货号"" AS text)) END AS main_key, CASE WHEN trim(cast(""出库SKU分类"" AS text)) = '辅助条码' THEN upper(trim(cast(""系统SKU"" AS text))) ELSE trim(cast(""系统SKU"" AS text)) END AS seed_sku FROM ""ERP"" WHERE trim(coalesce(cast(""店铺ID"" AS text), '')) <> '' AND trim(coalesce(cast(""出库SKU分类"" AS text), '')) <> '' AND ( trim(coalesce(cast(""主货号"" AS text), '')) <> '' OR upper(trim(cast(""系统SKU"" AS text))) IN ('TDZY123456', 'BDZY666888') ) ), seed_union AS ( SELECT shop_id, shop, category, main_key, seed_sku FROM seed_from_board UNION ALL SELECT shop_id, shop, category, main_key, seed_sku FROM seed_from_erp ), seed_keys AS ( SELECT shop_id, max(shop) AS shop, category, main_key, shop_id || '-' || category || '-' || main_key AS kid, max(seed_sku) AS seed_sku FROM seed_union WHERE shop_id <> '' AND category <> '' AND main_key <> '' GROUP BY shop_id, category, main_key ), board_metrics AS ( SELECT ( lower(trim(cast(""店铺ID"" AS text))) || '-' || trim(cast(""SPU分类"" AS text)) || '-' || CASE WHEN trim(cast(""主商品货号"" AS text)) LIKE '测品-%' THEN trim(cast(""主商品货号"" AS text)) WHEN trim(cast(""主商品货号"" AS text)) LIKE 'TEST-%' THEN trim(cast(""主商品货号"" AS text)) WHEN instr(trim(cast(""主商品货号"" AS text)), '-') > 0 THEN substr(trim(cast(""主商品货号"" AS text)), 1, instr(trim(cast(""主商品货号"" AS text)), '-') - 1) ELSE trim(cast(""主商品货号"" AS text)) END ) AS kid, max(lower(trim(cast(""店铺"" AS text)))) AS shop, max(trim(cast(""SPU分类"" AS text))) AS category, max( CASE WHEN trim(coalesce(cast(""主货号"" AS text), '')) <> '' THEN trim(cast(""主货号"" AS text)) ELSE trim(cast(""主商品货号"" AS text)) END ) AS board_main_sku, max( CASE WHEN instr(trim(cast(""主商品货号"" AS text)), '-') > 0 THEN substr(trim(cast(""主商品货号"" AS text)), 1, instr(trim(cast(""主商品货号"" AS text)), '-') - 1) ELSE trim(cast(""主商品货号"" AS text)) END ) AS main_key, SUM(CASE WHEN trim(cast(""商品访客（访问）"" AS text)) <> '-' THEN CAST(""商品访客（访问）"" AS REAL) ELSE 0 END) AS visit_sum, SUM(CASE WHEN trim(cast(""商品访客（访问）"" AS text)) <> '-' THEN CAST(""商品访客（添加至购物车）"" AS REAL) ELSE 0 END) AS add_cart_sum FROM ""大盘"" WHERE trim(coalesce(cast(""店铺ID"" AS text), '')) <> '' AND trim(coalesce(cast(""主商品货号"" AS text), '')) NOT IN ('', '#N/A') GROUP BY kid ), order_metrics AS ( SELECT ( lower(trim(cast(""店铺ID"" AS text))) || '-' || trim(cast(""SPU分类"" AS text)) || '-' || CASE WHEN trim(cast(""Parent SKU Reference No."" AS text)) LIKE '测品-%' THEN trim(cast(""Parent SKU Reference No."" AS text)) WHEN trim(cast(""Parent SKU Reference No."" AS text)) LIKE 'TEST-%' THEN trim(cast(""Parent SKU Reference No."" AS text)) WHEN instr(trim(cast(""Parent SKU Reference No."" AS text)), '-') > 0 THEN substr(trim(cast(""Parent SKU Reference No."" AS text)), 1, instr(trim(cast(""Parent SKU Reference No."" AS text)), '-') - 1) ELSE trim(cast(""Parent SKU Reference No."" AS text)) END ) AS kid, COUNT(DISTINCT trim(cast(""Order ID"" AS text))) AS order_cnt, SUM(COALESCE(CAST(""Quantity"" AS REAL), 0)) AS quantity_sum FROM ""订单"" WHERE trim(coalesce(cast(""店铺ID"" AS text), '')) <> '' AND trim(coalesce(cast(""SKU Reference No."" AS text), '')) NOT IN ('测品出单', 'TDZY123456', 'bdzy666888', 'BDZY666888') AND trim(coalesce(cast(""Order Status"" AS text), '')) NOT IN ('ยกเลิกแล้ว', 'Cancelled') AND NOT ( trim(coalesce(cast(""店铺ID"" AS text), '')) IN ('1015181313', '1473379246') AND trim(coalesce(cast(""SKU Reference No."" AS text), '')) LIKE 'DT%' ) GROUP BY kid ), ads_metrics AS ( SELECT ( lower(trim(cast(""店铺ID"" AS text))) || '-' || trim(cast(""SPU分类"" AS text)) || '-' || CASE WHEN trim(cast(""主货号"" AS text)) LIKE '测品-%' THEN trim(cast(""主货号"" AS text)) WHEN trim(cast(""主货号"" AS text)) LIKE 'TEST-%' THEN trim(cast(""主货号"" AS text)) WHEN instr(trim(cast(""主货号"" AS text)), '-') > 0 THEN substr(trim(cast(""主货号"" AS text)), 1, instr(trim(cast(""主货号"" AS text)), '-') - 1) ELSE trim(cast(""主货号"" AS text)) END ) AS kid, SUM(COALESCE(CAST(""花费"" AS REAL), 0)) AS ad_cost_sum FROM ""广告"" WHERE trim(coalesce(cast(""店铺ID"" AS text), '')) <> '' AND trim(coalesce(cast(""主货号"" AS text), '')) <> '' GROUP BY kid ), alli_metrics AS ( SELECT ( lower(trim(cast(""店铺ID"" AS text))) || '-' || trim(cast(""SPU分类"" AS text)) || '-' || CASE WHEN trim(cast(""主货号"" AS text)) LIKE '测品-%' THEN trim(cast(""主货号"" AS text)) WHEN trim(cast(""主货号"" AS text)) LIKE 'TEST-%' THEN trim(cast(""主货号"" AS text)) WHEN instr(trim(cast(""主货号"" AS text)), '-') > 0 THEN substr(trim(cast(""主货号"" AS text)), 1, instr(trim(cast(""主货号"" AS text)), '-') - 1) ELSE trim(cast(""主货号"" AS text)) END ) AS kid, SUM(COALESCE(CAST(""花费"" AS REAL), 0)) AS alli_cost_sum FROM ""联盟"" WHERE trim(coalesce(cast(""店铺ID"" AS text), '')) <> '' AND trim(coalesce(cast(""主货号"" AS text), '')) <> '' GROUP BY kid ), erp_metrics AS ( SELECT ( lower(trim(cast(""店铺ID"" AS text))) || '-' || CASE WHEN upper(trim(cast(""系统SKU"" AS text))) = 'BDZY666888' THEN trim(cast(""出库SKU分类"" AS text)) ELSE trim(cast(""商品分类2"" AS text)) END || '-' || CASE WHEN upper(trim(cast(""系统SKU"" AS text))) = 'BDZY666888' THEN upper(trim(cast(""系统SKU"" AS text))) ELSE trim(cast(""主货号"" AS text)) END ) AS kid, SUM(COALESCE(CAST(trim(""商品优惠后金额"") AS REAL), 0)) + SUM(COALESCE(CAST(trim(""买家实付运费"") AS REAL), 0)) AS sales_sum, SUM(COALESCE(CAST(trim(""订单收入"") AS REAL), 0)) AS order_sale_sum, ABS(SUM(COALESCE(CAST(trim(""采购成本"") AS REAL), 0))) AS buy_cost_sum, ABS(SUM(COALESCE(CAST(trim(""交易手续费"") AS REAL), 0) + COALESCE(CAST(trim(""佣金"") AS REAL), 0) + COALESCE(CAST(trim(""服务费"") AS REAL), 0))) AS platform_fee_sum, SUM(ABS(COALESCE(CAST(trim(""买家实付运费"") AS REAL), 0)) + ABS(COALESCE(CAST(trim(""交易手续费"") AS REAL), 0)) + ABS(COALESCE(CAST(trim(""佣金"") AS REAL), 0)) + ABS(COALESCE(CAST(trim(""服务费"") AS REAL), 0)) + 7.88) AS yingxiao_fee_sum FROM ""ERP"" WHERE trim(coalesce(cast(""店铺ID"" AS text), '')) <> '' AND NOT ( trim(coalesce(cast(""店铺ID"" AS text), '')) IN ('1015181313', '1473379246') AND trim(coalesce(cast(""系统SKU"" AS text), '')) LIKE 'DT%' ) GROUP BY kid ), final_base AS ( SELECT s.shop_id, s.shop, s.category, s.main_key, s.kid, s.seed_sku, b.board_main_sku, COALESCE(b.visit_sum, 0) AS visit_sum, COALESCE(b.add_cart_sum, 0) AS add_cart_sum, COALESCE(o.order_cnt, 0) AS order_cnt, COALESCE(o.quantity_sum, 0) AS quantity_sum, COALESCE(e.sales_sum, 0) AS sales_sum, COALESCE(e.order_sale_sum, 0) AS order_sale_sum, COALESCE(e.platform_fee_sum, 0) AS platform_fee_sum, COALESCE(e.buy_cost_sum, 0) AS buy_cost_sum, COALESCE(e.yingxiao_fee_sum, 0) AS ceping_marketing_cost, COALESCE(a.ad_cost_sum, 0) AS ad_cost_sum, COALESCE(l.alli_cost_sum, 0) AS alli_cost_sum FROM seed_keys s LEFT JOIN board_metrics b ON s.kid = b.kid LEFT JOIN order_metrics o ON s.kid = o.kid LEFT JOIN ads_metrics a ON s.kid = a.kid LEFT JOIN alli_metrics l ON s.kid = l.kid LEFT JOIN erp_metrics e ON s.kid = e.kid ) SELECT shop_id AS ""店铺ID"", CASE WHEN kid = '1736897676-辅助条码-TDZY123456' THEN '泰国-shopee-c店-veloree | home decor' ELSE shop END AS ""店铺"", category AS ""SPU分类"", kid AS ""KID"", params.week_label AS ""周"", params.date_label AS ""日期"", ceping_marketing_cost AS ""测评营销成本"", COALESCE(board_main_sku, seed_sku) AS ""主货号"", visit_sum AS ""访客数"", add_cart_sum AS ""加入购物车"", order_cnt AS ""订单数"", quantity_sum AS ""件数"", sales_sum AS ""销售额"", order_sale_sum AS ""订单收入"", platform_fee_sum AS ""平台费用"", CASE WHEN nullif(sales_sum, 0) IS NULL THEN NULL ELSE platform_fee_sum * 1.0 / sales_sum END AS ""平台费用占比"", buy_cost_sum AS ""采购总成本"", NULL AS ""自配送费用"", order_sale_sum - buy_cost_sum AS ""产品毛利润"", CASE WHEN nullif(sales_sum, 0) IS NULL THEN NULL ELSE (order_sale_sum - buy_cost_sum) * 1.0 / sales_sum END AS ""产品毛利润率"", ad_cost_sum AS ""广告成本"", alli_cost_sum AS ""联盟营销"", NULL AS ""测评费用"", CASE WHEN seed_sku IN ('TDZY123456', 'BDZY666888') THEN ceping_marketing_cost ELSE ad_cost_sum END AS ""营销成本"", CASE WHEN nullif(sales_sum, 0) IS NULL THEN NULL ELSE (CASE WHEN seed_sku IN ('TDZY123456', 'BDZY666888') THEN ceping_marketing_cost ELSE ad_cost_sum + alli_cost_sum END) * 1.0 / sales_sum END AS ""营销占比"", (order_sale_sum - buy_cost_sum) - (CASE WHEN seed_sku IN ('TDZY123456', 'BDZY666888') THEN ceping_marketing_cost ELSE ad_cost_sum + alli_cost_sum END) AS ""市场毛利润"", CASE WHEN nullif(sales_sum, 0) IS NULL THEN NULL ELSE ((order_sale_sum - buy_cost_sum) - (CASE WHEN seed_sku IN ('TDZY123456', 'BDZY666888') THEN ceping_marketing_cost ELSE ad_cost_sum + alli_cost_sum END)) * 1.0 / sales_sum END AS ""毛利润率"", CASE WHEN nullif(visit_sum, 0) IS NULL THEN NULL ELSE add_cart_sum * 1.0 / visit_sum END AS ""加购率"", CASE WHEN nullif(visit_sum, 0) IS NULL THEN NULL ELSE order_cnt * 1.0 / visit_sum END AS ""访问到下单转化率"", CASE WHEN nullif(add_cart_sum, 0) IS NULL THEN NULL ELSE order_cnt * 1.0 / add_cart_sum END AS ""加购到下单转化率"", CASE WHEN nullif(order_cnt, 0) IS NULL THEN NULL ELSE ad_cost_sum * 1.0 / order_cnt END AS ""获客成本/票"", CASE WHEN nullif(sales_sum, 0) IS NULL THEN NULL ELSE ad_cost_sum * 1.0 / sales_sum END AS ""获客成本占比/票"", CASE WHEN nullif(quantity_sum, 0) IS NULL THEN NULL ELSE ad_cost_sum * 1.0 / quantity_sum END AS ""获客成本/件"", CASE WHEN nullif((CASE WHEN seed_sku IN ('TDZY123456', 'BDZY666888') THEN ceping_marketing_cost ELSE ad_cost_sum + alli_cost_sum END), 0) IS NULL THEN NULL ELSE (order_sale_sum - buy_cost_sum) * 1.0 / (CASE WHEN seed_sku IN ('TDZY123456', 'BDZY666888') THEN ceping_marketing_cost ELSE ad_cost_sum + alli_cost_sum END) END AS ""投产比"", CASE WHEN nullif(order_cnt, 0) IS NULL THEN NULL ELSE sales_sum * 1.0 / order_cnt END AS ""客单价"", CASE WHEN nullif(order_cnt, 0) IS NULL THEN NULL ELSE (((order_sale_sum - buy_cost_sum) - (CASE WHEN seed_sku IN ('TDZY123456', 'BDZY666888') THEN ceping_marketing_cost ELSE ad_cost_sum + alli_cost_sum END)) * 1.0 / order_cnt) END AS ""客单净利润"", CASE WHEN nullif(quantity_sum, 0) IS NULL THEN NULL ELSE (((order_sale_sum - buy_cost_sum) - (CASE WHEN seed_sku IN ('TDZY123456', 'BDZY666888') THEN ceping_marketing_cost ELSE ad_cost_sum + alli_cost_sum END)) * 1.0 / quantity_sum) END AS ""件净利润"", '' AS ""币种"", NULL AS ""单个UV成本"", NULL AS ""单个加购成本"", NULL AS ""备注（平台抽成+客户运费+福利券折扣比例）"", NULL AS ""库存"", NULL AS ""含广告税 广告成本"", NULL AS ""含广告税 市场毛利润"", NULL AS ""含广告税 市场毛利率"" FROM final_base CROSS JOIN params ORDER BY kid")